import os, subprocess, sys, textwrap
open("repro_sana.py", "w").write('"""Reproduction: SanaPipeline scheduler add_noise() before set_timesteps().\n\nThe script encodes one image with the SANA VAE. It noises the latent with\npipe.scheduler.add_noise and does not call set_timesteps, as a fine-tune or probe script does.\nThen the transformer gives a one-step clean estimate. The script repeats this with the\nexpected flow noise x_t = (1 - t/1000) * x0 + (t/1000) * eps.\n\nUsage: python repro_sana.py [--model ID] [--device cuda] [--dtype bfloat16] [--image PATH]\n"""\n\nimport argparse\n\nimport torch\nfrom diffusers import SanaPipeline\nfrom diffusers.utils import load_image\n\nparser = argparse.ArgumentParser()\nparser.add_argument("--model", default="Efficient-Large-Model/Sana_1600M_1024px_BF16_diffusers")\nparser.add_argument("--device", default="cuda")\nparser.add_argument("--dtype", default="bfloat16", choices=["bfloat16", "float32"])\nparser.add_argument("--size", type=int, default=1024)\nparser.add_argument(\n    "--text-encoder-device", default=None, help="Run the text encoder here, for example cpu on a 16 GB GPU."\n)\nparser.add_argument(\n    "--image",\n    default="https://huggingface.co/datasets/huggingface/documentation-images/resolve/main/diffusers/astronaut.jpg",\n)\nargs = parser.parse_args()\ndtype = getattr(torch, args.dtype)\n\npipe = SanaPipeline.from_pretrained(args.model, torch_dtype=dtype)\nte_device = args.text_encoder_device or args.device\npipe.text_encoder.to(te_device)\nwith torch.no_grad():\n    embeds, mask, _, _ = pipe.encode_prompt("", do_classifier_free_guidance=False, device=te_device)\nembeds, mask = embeds.to(args.device), mask.to(args.device)\npipe.text_encoder = None\npipe.transformer.to(args.device)\npipe.vae.to(args.device)\nimage = pipe.image_processor.preprocess(load_image(args.image), height=args.size, width=args.size)\nwith torch.no_grad():\n    x0 = pipe.vae.encode(image.to(args.device, dtype)).latent * pipe.vae.config.scaling_factor\n    eps = torch.randn(x0.shape, generator=torch.Generator().manual_seed(0)).to(args.device, dtype)\n\n    print(f"{\'t\':>4} | {\'a (x0)\':>8} {\'b (eps)\':>8} | error with add_noise | error with flow noise")\n    for t in (200, 500, 800):\n        timestep = torch.tensor([t], device=args.device)\n        sigma = t / 1000\n        expected = (1 - sigma) * x0 + sigma * eps\n        noised = pipe.scheduler.add_noise(x0, eps, timestep)\n        # Least squares fit noised = a * x0 + b * eps shows the noise level that add_noise used.\n        design = torch.stack([x0.flatten(), eps.flatten()], 1).float()\n        a, b = torch.linalg.lstsq(design, noised.flatten().float()[:, None]).solution.flatten().tolist()\n        errors = []\n        for x_t in (noised, expected):\n            v = pipe.transformer(\n                x_t,\n                encoder_hidden_states=embeds,\n                encoder_attention_mask=mask,\n                timestep=timestep,\n                return_dict=False,\n            )[0]\n            x0_hat = x_t.float() - sigma * v.float()\n            errors.append(((x0_hat - x0.float()).norm() / x0.float().norm()).item())\n        print(f"{t:>4} | {a:8.3f} {b:8.3f} | {errors[0]:20.3f} | {errors[1]:21.3f}")\n')
open("fix.patch", "w").write('diff --git a/src/diffusers/schedulers/scheduling_deis_multistep.py b/src/diffusers/schedulers/scheduling_deis_multistep.py\nindex c22d2b5..2ddbd8e 100644\n--- a/src/diffusers/schedulers/scheduling_deis_multistep.py\n+++ b/src/diffusers/schedulers/scheduling_deis_multistep.py\n@@ -216,7 +216,12 @@ class DEISMultistepScheduler(SchedulerMixin, ConfigMixin):\n         self.alpha_t = torch.sqrt(self.alphas_cumprod)\n         self.sigma_t = torch.sqrt(1 - self.alphas_cumprod)\n         self.lambda_t = torch.log(self.alpha_t) - torch.log(self.sigma_t)\n-        self.sigmas = ((1 - self.alphas_cumprod) / self.alphas_cumprod) ** 0.5\n+        # `add_noise` reads `sigmas[i]` for `timesteps[i]`, and the timesteps below are descending.\n+        # Flow sigmas are in [0, 1] and equal `timestep / num_train_timesteps`.\n+        if use_flow_sigmas:\n+            self.sigmas = torch.arange(num_train_timesteps - 1, -1, -1, dtype=torch.float32) / num_train_timesteps\n+        else:\n+            self.sigmas = (((1 - self.alphas_cumprod) / self.alphas_cumprod) ** 0.5).flip(0)\n \n         # standard deviation of the initial noise distribution\n         self.init_noise_sigma = 1.0\ndiff --git a/src/diffusers/schedulers/scheduling_dpmsolver_multistep.py b/src/diffusers/schedulers/scheduling_dpmsolver_multistep.py\nindex edcfa45..904e03c 100644\n--- a/src/diffusers/schedulers/scheduling_dpmsolver_multistep.py\n+++ b/src/diffusers/schedulers/scheduling_dpmsolver_multistep.py\n@@ -302,7 +302,12 @@ class DPMSolverMultistepScheduler(SchedulerMixin, ConfigMixin):\n         self.alpha_t = torch.sqrt(self.alphas_cumprod)\n         self.sigma_t = torch.sqrt(1 - self.alphas_cumprod)\n         self.lambda_t = torch.log(self.alpha_t) - torch.log(self.sigma_t)\n-        self.sigmas = ((1 - self.alphas_cumprod) / self.alphas_cumprod) ** 0.5\n+        # `add_noise` reads `sigmas[i]` for `timesteps[i]`, and the timesteps below are descending.\n+        # Flow sigmas are in [0, 1] and equal `timestep / num_train_timesteps`.\n+        if use_flow_sigmas:\n+            self.sigmas = torch.arange(num_train_timesteps - 1, -1, -1, dtype=torch.float32) / num_train_timesteps\n+        else:\n+            self.sigmas = (((1 - self.alphas_cumprod) / self.alphas_cumprod) ** 0.5).flip(0)\n \n         # standard deviation of the initial noise distribution\n         self.init_noise_sigma = 1.0\ndiff --git a/src/diffusers/schedulers/scheduling_dpmsolver_singlestep.py b/src/diffusers/schedulers/scheduling_dpmsolver_singlestep.py\nindex 7a63d0b..867e8a6 100644\n--- a/src/diffusers/schedulers/scheduling_dpmsolver_singlestep.py\n+++ b/src/diffusers/schedulers/scheduling_dpmsolver_singlestep.py\n@@ -217,7 +217,12 @@ class DPMSolverSinglestepScheduler(SchedulerMixin, ConfigMixin):\n         self.alpha_t = torch.sqrt(self.alphas_cumprod)\n         self.sigma_t = torch.sqrt(1 - self.alphas_cumprod)\n         self.lambda_t = torch.log(self.alpha_t) - torch.log(self.sigma_t)\n-        self.sigmas = ((1 - self.alphas_cumprod) / self.alphas_cumprod) ** 0.5\n+        # `add_noise` reads `sigmas[i]` for `timesteps[i]`, and the timesteps below are descending.\n+        # Flow sigmas are in [0, 1] and equal `timestep / num_train_timesteps`.\n+        if use_flow_sigmas:\n+            self.sigmas = torch.arange(num_train_timesteps - 1, -1, -1, dtype=torch.float32) / num_train_timesteps\n+        else:\n+            self.sigmas = (((1 - self.alphas_cumprod) / self.alphas_cumprod) ** 0.5).flip(0)\n \n         # standard deviation of the initial noise distribution\n         self.init_noise_sigma = 1.0\ndiff --git a/src/diffusers/schedulers/scheduling_unipc_multistep.py b/src/diffusers/schedulers/scheduling_unipc_multistep.py\nindex 5c2cbcc..45ee4ba 100644\n--- a/src/diffusers/schedulers/scheduling_unipc_multistep.py\n+++ b/src/diffusers/schedulers/scheduling_unipc_multistep.py\n@@ -264,7 +264,12 @@ class UniPCMultistepScheduler(SchedulerMixin, ConfigMixin):\n         self.alpha_t = torch.sqrt(self.alphas_cumprod)\n         self.sigma_t = torch.sqrt(1 - self.alphas_cumprod)\n         self.lambda_t = torch.log(self.alpha_t) - torch.log(self.sigma_t)\n-        self.sigmas = ((1 - self.alphas_cumprod) / self.alphas_cumprod) ** 0.5\n+        # `add_noise` reads `sigmas[i]` for `timesteps[i]`, and the timesteps below are descending.\n+        # Flow sigmas are in [0, 1] and equal `timestep / num_train_timesteps`.\n+        if use_flow_sigmas:\n+            self.sigmas = torch.arange(num_train_timesteps - 1, -1, -1, dtype=torch.float32) / num_train_timesteps\n+        else:\n+            self.sigmas = (((1 - self.alphas_cumprod) / self.alphas_cumprod) ** 0.5).flip(0)\n \n         # standard deviation of the initial noise distribution\n         self.init_noise_sigma = 1.0\ndiff --git a/tests/schedulers/test_scheduler_dpm_multi.py b/tests/schedulers/test_scheduler_dpm_multi.py\nindex 28c3547..b02eab8 100644\n--- a/tests/schedulers/test_scheduler_dpm_multi.py\n+++ b/tests/schedulers/test_scheduler_dpm_multi.py\n@@ -4,6 +4,7 @@ import unittest\n import torch\n \n from diffusers import (\n+    DDPMScheduler,\n     DEISMultistepScheduler,\n     DPMSolverMultistepScheduler,\n     DPMSolverSinglestepScheduler,\n@@ -366,3 +367,82 @@ class DPMSolverMultistepSchedulerTest(SchedulerCommonTest):\n \n     def test_exponential_sigmas(self):\n         self.check_over_configs(use_exponential_sigmas=True)\n+\n+    def get_common_config(self, **kwargs):\n+        # Only keys that all four scheduler classes accept.\n+        config = {\n+            "num_train_timesteps": 1000,\n+            "beta_start": 0.0001,\n+            "beta_end": 0.02,\n+            "beta_schedule": "linear",\n+            "solver_order": 2,\n+            "prediction_type": "epsilon",\n+        }\n+        config.update(**kwargs)\n+        return config\n+\n+    def get_add_noise_coefficients(self, scheduler, timestep):\n+        # Use x0 = 1, eps = 0 for the first coefficient and x0 = 0, eps = 1 for the second.\n+        timesteps = torch.tensor([timestep])\n+        one = torch.ones(1, 1)\n+        zero = torch.zeros(1, 1)\n+        return scheduler.add_noise(one, zero, timesteps).item(), scheduler.add_noise(zero, one, timesteps).item()\n+\n+    def test_add_noise_without_set_timesteps(self):\n+        # `add_noise` must give the noise level of the given timestep when `set_timesteps` was not called.\n+        reference = DDPMScheduler(beta_start=0.0001, beta_end=0.02, beta_schedule="linear")\n+        for scheduler_class in (\n+            DPMSolverMultistepScheduler,\n+            DPMSolverSinglestepScheduler,\n+            UniPCMultistepScheduler,\n+            DEISMultistepScheduler,\n+        ):\n+            scheduler = scheduler_class(**self.get_common_config())\n+            for timestep in (0, 200, 500, 800, 999):\n+                expected = self.get_add_noise_coefficients(reference, timestep)\n+                actual = self.get_add_noise_coefficients(scheduler, timestep)\n+                assert abs(actual[0] - expected[0]) < 1e-4 and abs(actual[1] - expected[1]) < 1e-4, (\n+                    f"{scheduler_class.__name__}, t={timestep}: expected {expected}, got {actual}"\n+                )\n+\n+    def test_add_noise_without_set_timesteps_flow_sigmas(self):\n+        # Flow sigmas are in [0, 1], so x_t = (1 - t / 1000) * x0 + (t / 1000) * eps.\n+        for scheduler_class in (\n+            DPMSolverMultistepScheduler,\n+            DPMSolverSinglestepScheduler,\n+            UniPCMultistepScheduler,\n+            DEISMultistepScheduler,\n+        ):\n+            scheduler = scheduler_class(\n+                **self.get_common_config(prediction_type="flow_prediction", use_flow_sigmas=True, flow_shift=3.0)\n+            )\n+            for timestep in (0, 200, 500, 800, 999):\n+                actual = self.get_add_noise_coefficients(scheduler, timestep)\n+                expected = (1 - timestep / 1000, timestep / 1000)\n+                assert abs(actual[0] - expected[0]) < 1e-4 and abs(actual[1] - expected[1]) < 1e-4, (\n+                    f"{scheduler_class.__name__}, t={timestep}: expected {expected}, got {actual}"\n+                )\n+\n+    def test_add_noise_after_set_timesteps_matches_before(self):\n+        # `set_timesteps` must keep the same noise level for a timestep that it keeps.\n+        for use_flow_sigmas in (False, True):\n+            config = self.get_common_config(final_sigmas_type="zero")\n+            if use_flow_sigmas:\n+                config.update(prediction_type="flow_prediction", use_flow_sigmas=True, flow_shift=3.0)\n+            scheduler = DPMSolverMultistepScheduler(**config)\n+            before = {t: self.get_add_noise_coefficients(scheduler, t) for t in (0, 200, 500, 800, 999)}\n+            scheduler.set_timesteps(50)\n+            for timestep in scheduler.timesteps.tolist():\n+                expected = (\n+                    (1 - timestep / 1000, timestep / 1000)\n+                    if use_flow_sigmas\n+                    else self.get_add_noise_coefficients(\n+                        DDPMScheduler(beta_start=0.0001, beta_end=0.02, beta_schedule="linear"), timestep\n+                    )\n+                )\n+                actual = self.get_add_noise_coefficients(scheduler, timestep)\n+                # The flow timesteps are rounded down to integers, so the tolerance is larger.\n+                tolerance = 2e-3 if use_flow_sigmas else 1e-4\n+                assert abs(actual[0] - expected[0]) < tolerance and abs(actual[1] - expected[1]) < tolerance\n+                if timestep in before:\n+                    assert abs(actual[0] - before[timestep][0]) < 2e-3\n')
def sh(cmd):
    print("+", cmd, flush=True)
    subprocess.run(cmd, shell=True, check=True)
sh("nvidia-smi --query-gpu=name,memory.total --format=csv")
sh("pip uninstall -y -q torchao")  # the preinstalled torchao is too old for diffusers 0.41
sh("pip install -q -U 'diffusers==0.41.0' transformers accelerate sentencepiece")
sh("python -c \"import torch, diffusers, transformers; print(torch.__version__, diffusers.__version__, transformers.__version__, torch.cuda.get_device_name(0))\"")
args = "--dtype float32 --text-encoder-device cpu"
print("\n===== A: diffusers 0.41.0 from PyPI =====", flush=True)
sh(f"python repro_sana.py {args}")
print("\n===== B: diffusers main with the fix =====", flush=True)
sh("git clone -q --depth 1 https://github.com/huggingface/diffusers dsrc && cd dsrc && git log -1 --format=%h && git apply ../fix.patch && git status --short")
sh(f"PYTHONPATH=dsrc/src python repro_sana.py {args}")

sh("rm -rf dsrc")  # keep the output small, so the log download stays fast
